begin;

create or replace function private.official_subclass_spell_mechanic(
  p_class_key text,
  p_source_key text,
  p_slug text,
  p_fallback_name text,
  p_fallback_level integer,
  p_mode text
)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_spell public.spell_catalog%rowtype;
  v_name text;
  v_level integer;
  v_options jsonb;
  v_ability text;
begin
  select * into v_spell from public.spell_catalog where slug=p_slug limit 1;
  v_name := coalesce(nullif(v_spell.name_ru,''),nullif(v_spell.name_en,''),p_fallback_name);
  v_level := coalesce(v_spell.spell_level,greatest(0,least(9,p_fallback_level)));
  v_ability := case when p_class_key in ('fighter','rogue') then 'intelligence'
    when p_class_key in ('artificer','wizard') then 'intelligence'
    when p_class_key in ('cleric','druid','monk','ranger') then 'wisdom'
    else 'charisma' end;

  if v_level=0 then
    v_options := '[]'::jsonb;
  elsif p_class_key='warlock' then
    v_options := jsonb_build_array(jsonb_build_object(
      'key','pact-slot','castLevel',v_level,
      'costs',jsonb_build_array(jsonb_build_object('key','pact_slots','amount',1))
    ));
  elsif p_class_key in ('barbarian','monk') then
    v_options := '[]'::jsonb;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'key','slot-' || s::text,'castLevel',s,
      'costs',jsonb_build_array(jsonb_build_object('key','spell_slot_' || s::text,'amount',1))
    ) order by s),'[]'::jsonb)
    into v_options
    from generate_series(greatest(1,v_level),9) s;
  end if;

  return jsonb_build_object(
    'id',p_class_key || '-' || p_source_key || '-spell-' || p_slug,
    'type','spell','sourceKey',p_source_key,'variantKey',p_source_key || ':' || p_slug,
    'key','spell:' || p_slug,
    'payload',jsonb_build_object(
      'spell',jsonb_build_object('name',v_name,'level',v_level),
      'preparation',jsonb_build_object('mode',case when p_mode='always_prepared' then 'always_prepared' else 'prepared' end),
      'methods',jsonb_build_array(jsonb_build_object(
        'key',p_source_key || '-access','kind','subclass_spell','ability',v_ability,
        'requiresPrepared',p_mode<>'always_prepared','resourceOptions',v_options
      ))
    )
  );
end;
$$;

