","priority":70}}]}],"spells":[{"unlockLevel":6,"slug":"summon-beast","fallbackName":"Summon Beast","mode":"always_prepared"},{"unlockLevel":6,"slug":"summon-fey","fallbackName":"Summon Fey","mode":"always_prepared"},{"unlockLevel":3,"slug":"minor-illusion","fallbackName":"Minor Illusion","mode":"always_prepared"}]},{"classKey":"wizard","className":"Волшебник","slug":"wizard-bladesinger","name":"Певец клинка","summary":"Песнь клинка соединяет высокую защиту, скорость, оружие и магию.","source":"FRHoF","unlockLevel":3,"ability":"intelligence","author":"Песнь клинка соединяет высокую защиту, скорость, оружие и магию. Сначала разберитесь, когда способность включается и что расходует; красивое название ещё ни разу не вернуло потраченный заряд.","comment":"Школа учит делать несколько видов невозможного особенно хорошо. Остальные виды волшебник всё равно запишет в книгу — из зависти.","features":[{"level":3,"sourceKey":"bladesinger-l3-1","label":"Певец клинка","description":"На 3 уровне развивает направление «Певец клинка»: песнь клинка соединяет высокую защиту, скорость, оружие и магию.","mechanic":{"economy":null,"dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"recharge":[],"usesScale":null},"runtime":[]},{"level":6,"sourceKey":"extra-attack-l6-1","label":"Дополнительная атака","description":"На 6 уровне развивает направление «Певец клинка»: песнь клинка соединяет высокую защиту, скорость, оружие и магию. Применение: действие.","mechanic":{"economy":"action","dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"recharge":[],"usesScale":null},"runtime":[{"id":"wizard-extra-attack-l6-1-action-1","type":"action","sourceKey":"extra-attack-l6-1","key":"extra-attack-l6-1_action_1","label":"Дополнительная атака","economy":"action","range":{"kind":"self"},"tags":["unique","subclass","structured"],"presentation":{"tone":"cyan","icon":"◇","display":"counter","priority":70}}]},{"level":10,"sourceKey":"song-of-defense-l10-1","label":"Песня защиты","description":"На 10 уровне развивает направление «Певец клинка»: песнь клинка соединяет высокую защиту, скорость, оружие и магию. Применение: реакция.","mechanic":{"economy":"reaction","dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"recharge":[],"usesScale":null},"runtime":[{"id":"wizard-song-of-defense-l10-1-action-1","type":"action","sourceKey":"song-of-defense-l10-1","key":"song-of-defense-l10-1_action_1","label":"Песня защиты","economy":"reaction","range":{"kind":"self"},"tags":["unique","subclass","structured"],"presentation":{"tone":"cyan","icon":"◇","display":"counter","priority":70}}]},{"level":14,"sourceKey":"song-of-victory-l14-1","label":"Песня победы","description":"На 14 уровне развивает направление «Певец клинка»: песнь клинка соединяет высокую защиту, скорость, оружие и магию. Применение: бонусное действие.","mechanic":{"economy":"bonus_action","dice":[],"damageTypes":[],"savingThrows":[],"rangeFeet":[],"recharge":[],"usesScale":null},"runtime":[{"id":"wizard-song-of-victory-l14-1-action-1","type":"action","sourceKey":"song-of-victory-l14-1","key":"song-of-victory-l14-1_action_1","label":"Песня победы","economy":"bonus_action","range":{"kind":"self"},"tags":["unique","subclass","structured"],"presentation":{"tone":"cyan","icon":"◇","display":"counter","priority":70}}]}],"spells":[]}]$catalog$::jsonb;
  v_subclass jsonb;
  v_feature jsonb;
  v_spell jsonb;
  v_parent uuid;
  v_template uuid;
  v_level integer;
  v_level_mechanics jsonb;
begin
  perform private.install_official_class_catalog(p_campaign_id);

  for v_subclass in select value from jsonb_array_elements(v_catalog) loop
    select id into v_parent
    from public.rule_templates
    where campaign_id=p_campaign_id
      and kind='class'
      and catalog_key='class:' || (v_subclass->>'classKey')
      and is_builtin and is_active
    order by version desc limit 1;
    if v_parent is null then
      raise exception 'Parent class % is unavailable',v_subclass->>'classKey';
    end if;

    insert into public.rule_templates(
      campaign_id,kind,slug,name,description,version,mechanics,choices,parent_template_id,unlock_level,
      catalog_key,catalog_revision,source_kind,source_label,is_builtin,mechanical_summary,
      author_description,author_comment,rules_meta,created_by,is_active
    ) values (
      p_campaign_id,'subclass',v_subclass->>'slug',v_subclass->>'name',v_subclass->>'summary',1,
      '[]'::jsonb,'[]'::jsonb,v_parent,(v_subclass->>'unlockLevel')::integer,
      'subclass:' || (v_subclass->>'classKey') || ':' || regexp_replace(v_subclass->>'slug','^' || (v_subclass->>'classKey') || '-','','g'),
      'official-current@1','official',v_subclass->>'source',true,
      v_subclass->>'summary',v_subclass->>'author',v_subclass->>'comment',
      jsonb_build_object(
        'base_class','class:' || (v_subclass->>'classKey'),
        'source_code',v_subclass->>'source',
        'feature_levels',(select coalesce(jsonb_agg(distinct (f->>'level')::integer),'[]'::jsonb) from jsonb_array_elements(v_subclass->'features') f),
        'structured_runtime',true
      ),null,true
    )
    on conflict(campaign_id,kind,slug,version) do update set
      name=excluded.name,description=excluded.description,mechanics=excluded.mechanics,choices=excluded.choices,
      parent_template_id=excluded.parent_template_id,unlock_level=excluded.unlock_level,
      catalog_key=excluded.catalog_key,catalog_revision=excluded.catalog_revision,source_kind=excluded.source_kind,
      source_label=excluded.source_label,is_builtin=true,mechanical_summary=excluded.mechanical_summary,
      author_description=excluded.author_description,author_comment=excluded.author_comment,
      rules_meta=excluded.rules_meta,is_active=true,updated_at=now()
    returning id into v_template;

    delete from public.rule_template_levels where template_id=v_template;
    for v_level in 1..20 loop
      v_level_mechanics := '[]'::jsonb;
      for v_feature in select value from jsonb_array_elements(v_subclass->'features')
        where (value->>'level')::integer=v_level
      loop
        v_level_mechanics := v_level_mechanics || jsonb_build_array(jsonb_build_object(
          'id',(v_subclass->>'slug') || '-' || (v_feature->>'sourceKey') || '-feature',
          'type','grant','sourceKey',v_feature->>'sourceKey','target','feature',
          'key','subclass:' || (v_subclass->>'classKey') || ':' || regexp_replace(v_subclass->>'slug','^' || (v_subclass->>'classKey') || '-','','g') || ':' || (v_feature->>'sourceKey'),
          'payload',jsonb_build_object(
            'label',v_feature->>'label','description',v_feature->>'description',
            'mechanic',coalesce(v_feature->'mechanic','{}'::jsonb)
          )
        ));
        v_level_mechanics := v_level_mechanics || coalesce(v_feature->'runtime','[]'::jsonb);
      end loop;
      for v_spell in select value from jsonb_array_elements(v_subclass->'spells')
        where (value->>'unlockLevel')::integer=v_level
      loop
        v_level_mechanics := v_level_mechanics || jsonb_build_array(private.official_subclass_spell_mechanic(
          v_subclass->>'classKey','subclass-spells',v_spell->>'slug',v_spell->>'fallbackName',
          greatest(0,least(9,ceil(v_level::numeric/4.0)::integer)),v_spell->>'mode'
        ));
      end loop;
      if v_level_mechanics <> '[]'::jsonb then
        insert into public.rule_template_levels(template_id,level,mechanics,choices)
        values(v_template,v_level,v_level_mechanics,'[]'::jsonb);
      end if;
    end loop;
  end loop;
end;
$$;

create or replace function private.install_official_subclass_catalog_after_campaign()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.install_official_subclass_catalog(new.id);
  return new;
end;
$$;

drop trigger if exists campaigns_install_official_subclass_catalog on public.campaigns;
create trigger campaigns_install_official_subclass_catalog
after insert on public.campaigns
for each row execute function private.install_official_subclass_catalog_after_campaign();

do $$
declare v_campaign record;
begin
  for v_campaign in select id from public.campaigns loop
    perform private.install_official_subclass_catalog(v_campaign.id);
  end loop;
end;
$$;

commit;
